def payments_by_method(conn, method):
    """All payments made with one method, oldest first."""
    sql = (
        "SELECT id, method, amount_cents FROM payments "
        "WHERE method = '" + method + "' "
        "ORDER BY id"
    )
    return conn.execute(sql).fetchall()
